/// Animation sequence definition
///
/// Sequences define named animation clips with specific frame ranges. Examples: "Stand", "Walk", "Attack", "Death"
pub struct Sequence {
    pub(crate) raw: core::ptr::NonNull<ffi::whiteout_MdxSequence>,
}

impl Drop for Sequence {
    fn drop(&mut self) {
        // SAFETY: `raw` came from a native constructor and Drop runs once.
        unsafe { ffi::whiteout_mdx_MdxSequence_delete(self.raw.as_ptr()) }
    }
}

impl Sequence {
    /// # Safety
    /// `raw` must be a live handle this value takes ownership of.
    #[allow(dead_code)] // used by whichever methods return this type
    pub(crate) unsafe fn from_raw(raw: *mut ffi::whiteout_MdxSequence) -> Option<Self> {
        core::ptr::NonNull::new(raw).map(|raw| Sequence { raw })
    }
}

// SAFETY: handles are plain heap pointers with no thread affinity. `Sync`
// is deliberately NOT implemented — the C++ types make no documented
// guarantee about concurrent use, and claiming one we haven't verified
// would be unsound. See `@bind thread_safe` in the plan.
unsafe impl Send for Sequence {}

impl core::fmt::Debug for Sequence {
    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        f.debug_struct("Sequence").finish_non_exhaustive()
    }
}

